import { edit_presence_qrs } from "@/graphql/mutations.js";
import { API, graphqlOperation } from "aws-amplify";
export default {
  name: "DoorlockDialog",
  props: {
    modelValue: Boolean,
    item: Object
  },
  data() {
    return {
      loading: false,
      selectedQrIndex: null
    };
  },
  watch: {
    modelValue(newVal) {
      if (newVal) {
        // console.log(this.item)
        this.loading = false;
        // Reset selection when dialog opens
        this.selectedQrIndex = null;
        // Auto-select first QR if multiple exist
        if (this.item && this.item.qr_details && this.item.qr_details.length > 1) {
          this.selectedQrIndex = 0;
        }
      }
    }
  },
  methods: {
    getDoorLockStatus() {
      return this.item && this.item.qr_details && this.item.qr_details.length == 1 ? this.item.qr_details[0].is_door_lock === true : false;
    },
    getSelectedQrDoorLockStatus() {
      if (this.item && this.item.qr_details && this.item.qr_details.length > 1 && this.selectedQrIndex !== null) {
        return this.item.qr_details[this.selectedQrIndex].is_door_lock === true;
      }
      return false;
    },
    getSelectedQrLabel() {
      if (this.item && this.item.qr_details && this.item.qr_details.length > 1 && this.selectedQrIndex !== null) {
        return this.item.qr_details[this.selectedQrIndex].qr_label;
      }
      return this.item && this.item.qr_details && this.item.qr_details.length == 1 ? this.item.qr_details[0].qr_label : this.item.location_id;
    },
    closeDialog() {
      this.$emit("clicked", 0);
      this.$emit("update:modelValue", false);
    },
    async toggleDoorEnabled() {
      if (!this.item || !this.item.location_id) return;
      this.loading = true;
      try {
        const input = {
          qr_label: this.getSelectedQrLabel(),
          is_door_lock: this.item && this.item.qr_details && this.item.qr_details.length > 1 ? !this.getSelectedQrDoorLockStatus() : !this.getDoorLockStatus()
        };
        const result = await API.graphql(graphqlOperation(edit_presence_qrs, {
          input
        }));
        this.loading = false;
        let response = JSON.parse(result.data.edit_presence_qrs);
        if (response.Status === "SUCCESS") {
          this.$emit("successMsg", response.Message);
        } else {
          this.$emit("errorMsg", response.Message);
        }
        this.closeDialog();
      } catch (error) {
        this.loading = false;
        this.$emit("errorMsg", error.errors?.[0]?.message || "Error updating doorlock");
        this.closeDialog();
      }
    }
  }
};
